declaration.text:
ramify 1
module agent

// The port the harness core drives every agent through, and the scripted
// fake that implements it. How a session is driven stays behind the port.
// The port also reaches the implementations beneath this module.
expose-src * from "interfaces/port.ts" to parent, descendants
expose-src createScriptedAgent, ScriptStep, Script, ScriptedAgent, ScriptedAgentOptions, ScriptedSessionRecord, ScriptedToolResult, SessionScript, SessionScriptStep, createScriptedSessionDriver from "scripted.ts" to parent

// pi, the port's first real implementation, relayed to the harness that
// chooses it.
expose-sub * from pi to parent

expose-src * from "interfaces/session-operations.ts" to parent, descendants
expose-src createSessionOperations from "session-operations.ts" to parent, descendants

ramify 1
module pi

// The port's implementation on pi. The pi package, its session format and its
// login stay behind this boundary; nothing else in the project imports pi.
expose-src createPiAgent, piReadiness, PiAgentOptions from "pi-agent.ts" to parent

expose-src piBuiltinDeclarations from "session-operations.ts" to parent

// Qualification reads final request artifacts without decoding provider history.
expose-src readPiNativeRequestArtifact, PiNativeRequestArtifact from "preservation.ts" to parent

ramify 1
module audit

// The audit library and its evidence model stay behind this boundary. The
// parent receives the committed configured audit, its harness result with
// each nested project and the discovery outcome, and the durable
// workspace-ownership callback contract with its nested invocation receipt.
// No ramify-audit type crosses.
expose-src AuditCheckExecutionOptions, AuditWorkspaceOwnershipRecorder, IntendedAuditWorkspace from "check-execution.ts" to parent
expose-src AuditInvocationReceipt, AuditInvocationProject from "check-execution.ts" to parent
expose-src createConfiguredAudit, ConfiguredAuditPort, ConfiguredAuditInput, ConfiguredAuditMode, ConfiguredAuditReuse from "check-execution.ts" to parent
expose-src ConfiguredProjectResult, ConfiguredCountBucket, ConfiguredNestedDiscovery from "check-execution.ts" to parent
expose-src CommittedAuditConfiguration, ConfiguredAuditResult, ConfiguredFullAuditResult, configuredFullRecovery, readCommittedAuditConfiguration, sameAuditPolicy from "check-execution.ts" to parent
expose-src testLockedRunner, TestLockOwner, TestLockHooks, TestLockOverride from "test-lock.ts" to parent
expose-src dispatchHarnessCommand from "focused-check.ts" to parent

ramify 1
module check-findings

// CheckFindings as pure functions: the identity of an issue across reports,
// the decisions that may change it, the state replay derives and the views
// a query selects. The harness binds every reference it passes in and
// commits the returned events through its ledger. The contract file names
// every type a signature below mentions, so the parent can name what it
// receives.
expose-src * from "interfaces/check-findings.ts" to parent
expose-src decideCheckFindingChange from "decide.ts" to parent
expose-src applyCheckFindingEvent, replayCheckFindingEvents, emptyCheckFindingState from "replay.ts" to parent
expose-src selectCheckFindings from "queries.ts" to parent

ramify 1
module evidence

// Effective declared target Cucumber configuration, acquired through the injected command boundary.
expose-src CucumberConfigurationSelection, EffectiveCucumberConfiguration, CucumberConfigurationResult, loadCucumberConfiguration from "cucumber-configuration.ts" to parent

// Running the Ramify CLI: its exit codes and the private daemon stay here.
// The executable's own path crosses, because a run captures the complete
// command it ran the Ramify check with, environment included, and a captured
// command that names no executable cannot be run again.
expose-src RamifyCli, RamifyRun, RamifyCheckResult, CheckProvider, MaterializeResult, ramifyVersion, privateRamify, ramifyExecutable from "ramify-cli.ts" to parent

// Reading what Ramify generates: the architect view, a requester API view and
// the measurement document. Their file formats stay here.
expose-src architectViewDirectory, ArchitectMeta, readArchitectMeta, coverageLimitsOf, CoverageRecord, coverageRecordsOf, describeCoverageLimits, ApiViewDirectory, apiViewDirectoriesOf, ArchitectIndex, loadArchitectIndex, loadModuleTree from "views.ts" to parent
expose-src ModuleEntry, SymbolRecord, ExposureChannel, findModule, symbolRecords, SourceArea, ApiViewSnapshot, readApiView, findInView from "views.ts" to parent
expose-src isTestingModule from "views.ts" to parent
expose-src MeasurementDocument, ModuleMeasurement, MeasurementRead, readMeasurement, documentSchema, moduleSchema from "measure.ts" to parent

// Running one of the target project's own commands, in its own process group
// and with a clean environment.
expose-src CommandRunner, runCommand, CommandRequest, CommandRun, CommandOutcome, CommandOutput, childEnvironment, environmentNames, outputTailBytes, processGroupIdentity from "run-command.ts" to parent

// The target project's configuration for the harness, read as bytes; its
// schema and what an invalid file means belong to the harness.
expose-src projectConfigurationFile, ProjectConfigurationRead, readProjectConfiguration from "project-configuration.ts" to parent

// The identity of the state the evidence describes.
expose-src guardedFilesHash from "guarded-files.ts" to parent

// Git, for the run branch: a clean-repository check, the branch, the commit a
// gate audits, recovery by exact trailers, and what changed.
expose-src GitError, CommitTrailer, isCleanRepository, createRunBranch, commitAccepted, findCommitByTrailer, findCommitByTrailers, changedPaths, diffNumstat from "git.ts" to parent
expose-src commitNameStatus, diffNameStatus, worktreeLineChanges, worktreePatch, changedEntries from "git.ts" to parent

// A committed candidate read from Git's objects, which a review snapshot is
// served from: its tree, its files, a search and its diff from a base.
expose-src CandidateSource, gitCandidateSource, TreeEntry, TreeMatch, commitTree, treeEntries, readBlob, grepTree, diffPatch from "git.ts" to parent

// The history a run's delivered change is attributed from: the commits of
// a range, its direct diff and the commit Git names for each changed line.
expose-src ChangeHistory, ChangedFile, LineRange, GitLineRange, LineCommit, gitChangeHistory from "git.ts" to parent

// Consumers inject this boundary; real Git integration tests live with the adapter.
expose-src GitService, gitService, currentHead, resolveCommit, runBranchName, inspectRunBranch, recoveryStatus, isAncestor, commonDirectory from "git.ts" to parent
expose-src trackedPaths, ignoreStatus, IgnoreRule, IgnoreStatus from "git.ts" to parent
expose-src GitInspection, inspectGit from "git.ts" to parent
expose-src CandidateTreePreview, previewCandidateTree from "candidate-tree.ts" to parent

expose-src productionSourceGit, ProvisionalSourceGit from "provisional-git.ts" to parent

// Strict scripted check replies remain testing source in their owning adapter.
expose-test ScriptedCli, CliReply from "helpers/scripted-cli.ts" to parent

// Current ownership and unavailable acquisition retain their original evidence.
expose-src OwnershipAnswer, OwnershipPath, OwnershipQueryResult, RawOwnershipEvidence, OwnershipUnavailableError, OwnershipCancelledError, requireOwnershipAnswer, decodeOwnershipEvidenceAnswer, ownershipAnswerOfAffected from "ownership-evidence.ts" to parent
expose-src ProviderFailureEvidence, RecoveryEvidence from "provider-evidence.ts" to parent

expose-src resolveCommit from "git.ts" to parent

// Exact UTF-8 text from immutable blobs, authenticated against available entry metadata.
expose-src verifiedCandidateSource, readVerifiedTextBlobBytes, GitTextError from "git-text.ts" to parent

ramify 1
module kpi

// Per-invocation measurement; harness retains collection timing and durable writes.
expose-src LineChange, LineSnapshot, LineEventRequest, takeLineSnapshot, lineEvents from "lines.ts" to parent

// Scope accounting and factual delivered-support inputs used by collection/query consumers.
expose-src DeclaredScope, baselineScope, scopeSize, revisionMismatch, rootModuleOfSnapshot, captureSnapshot, SnapshotRequest, deliveredScopeInputs, DeliveredSupportEntry, DeliveredSupportSource, DeliveredScopeInputs from "capture.ts" to parent

// Invocation qualification receives facts; acquisition and timing stay with harness.
expose-src InvocationScopeDeclaration, invocationReadSize, invocationScopeSize, invocationScopeFailure from "capture.ts" to parent

// Pure provider behavior and all owner-local signature companions.
expose-src verifySetupLineIdentities, SetupLineIdentityInput, RecordedSetupDelta, SetupCandidatePartition, SetupLineMappingFacts, SetupSourceLine, SetupAddedLineFact, SetupDeletedLineFact from "setup-attribution.ts" to parent
expose-src HarnessLineIdentities, deliveredChange, DeliveredChangeRequest, DeliveredChange, cachedChangeHistory from "delivered.ts" to parent

// Recorded-fact calculation entry points for harness composition and projections.
expose-src kpiMetrics, comparableScopeMetrics, kpiPolicyVersion, measurementPolicyVersion, InvocationFacts, MetricInputs, ScopeComparison from "metrics.ts" to parent
expose-src lineageMetrics, lineagePolicyVersion, LineageInputs, SegmentFacts, SegmentUsage, StartKind from "lineage.ts" to parent
expose-src explorationDetails, ExplorationObservation, ExplorationMetrics, SearchCount, SearchCounts from "exploration.ts" to parent
expose-src invocationTiming, InvocationTiming, estimateRecordedCharge, ChargeInput, RecordedCharge from "efficiency.ts" to parent
expose-src guardingReport, GuardingReport, GuardVerdictCounts from "guarding.ts" to parent
// Session aggregation remains private; production projections use recorded facts.

ramify 1
module plan-evidence

// Captured source identity, the element catalog and its package creator
// belong to this child. The harness receives these contracts and remains
// the only durable writer.
expose-src * from "interfaces/contracts.ts" to parent
expose-src * from "interfaces/catalog.ts" to parent
expose-src discoverDocuments, nodeDocumentReader, DocumentReader, DiscoveredDocuments, DocumentDiscoveryOptions, OutsideDocumentReference, UnreadableDocumentReference from "discovery.ts" to parent

ramify 1
module session-store

// Durable session records and immutable payloads through the authoritative ledger.
// The parent composes workflow callers; this child decides no workflow outcome.
expose-src openSessionStore, LedgerSessionStoreOptions, LedgerSessionStore from "session-store.ts" to parent

// Workflow tests replace only persistence, retaining real session/workflow logic.
expose-test openMemorySessionStore, forgetMemorySessionStores from "helpers/memory-session-store.ts" to parent

ramify 1
// Browser code: it renders what the harness publishes and imports only the
// browser-safe contracts it receives from the root. It exposes nothing; the
// root reaches it only through its build output.
module web tagged [ui, browser]
